package com.disasterinfo.eodiisseo.disaster.collection;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import java.io.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.sql.DriverManager;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static com.disasterinfo.eodiisseo.disaster.collection.EarthquakeApiProbe.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class EarthquakeApiProbeTest {
    static final Clock CLOCK=Clock.fixed(Instant.parse("2026-11-10T03:00:00Z"),ZoneOffset.UTC);
    static final LocalDate DAY=LocalDate.of(2026,11,9);
    static final String KEY="SYNTHETIC_SECRET+/=DO_NOT_LOG";
    @TempDir Path temp;
    static Plan plan(Route r,Format f){return new Plan(r,DAY,DAY,1,1,f);}
    static Authorization allowed(Plan p){return new Authorization(p,CLOCK.instant().plusSeconds(300),CLOCK.instant().plusSeconds(600),1,true,true,true,true,"SYNTHETIC:APPROVAL");}
    static String item(){return "{\"stnId\":108,\"tmFc\":\"202611091200\",\"tmSeq\":1,\"fcTp\":3,\"cnt\":1,\"tmEqk\":\"20261109115930\",\"lat\":36.1,\"lon\":127.1,\"mt\":2.1,\"inT\":\"SYNTHETIC\",\"cor\":\"SYNTHETIC raw correction\"}";}
    static String json(String code,String message,int total,String rows){return "{\"response\":{\"header\":{\"resultCode\":\""+code+"\",\"resultMsg\":\""+message+"\"},\"body\":{\"pageNo\":1,\"numOfRows\":1,\"totalCount\":"+total+",\"items\":{\"item\":"+rows+"}}}}";}
    static String xml(String code,String message,int total,String item){return "<response><header><resultCode>"+code+"</resultCode><resultMsg>"+message+"</resultMsg></header><body><pageNo>1</pageNo><numOfRows>1</numOfRows><totalCount>"+total+"</totalCount><items>"+item+"</items></body></response>";}
    static String xmlItem(){return "<item><stnId>108</stnId><tmFc>202611091200</tmFc><tmSeq>1</tmSeq><fcTp>3</fcTp><tmEqk>20261109115930</tmEqk><lat>36.1</lat><lon>127.1</lon></item>";}
    static OfficialHttp.HeadersReply reply(int status,String body,Format f){return new OfficialHttp.HeadersReply(status,body.getBytes(StandardCharsets.UTF_8),List.of("1"),List.of(f==Format.JSON?"application/json; charset=utf-8":"application/xml"));}
    static EarthquakeApiProbe probe(Sender sender){return new EarthquakeApiProbe(sender,new Credentials(Map.of(Route.PORTAL,()->KEY,Route.HUB,()->KEY)),CLOCK);}
    static Observation observe(String body,Format f){var p=plan(Route.PORTAL,f);return probe((u,t)->reply(200,body,f)).observe(p,allowed(p));}
    @ParameterizedTest @EnumSource(Format.class) void normalJsonAndXmlObserveTypesWithoutRawValues(Format f){
        var o=observe(f==Format.JSON?json("00","OK",1,"["+item()+"]"):xml("0","NORMAL_SERVICE",1,xmlItem()),f);
        assertTrue(o.parsingSucceeded());assertTrue(o.httpNormal());assertTrue(o.providerNormal());assertTrue(o.earthquakeRowsReceived());assertEquals(1,o.itemCount());assertEquals(64,o.sha256().length());
        assertEquals(f==Format.JSON?"NUMBER":"STRING",o.items().getFirst().fields().get("stnId").type());assertEquals("VALID_12_DIGITS",o.items().getFirst().fields().get("tmFc").format());assertEquals("VALID_14_DIGITS",o.items().getFirst().fields().get("tmEqk").format());
        assertFalse(metadataJson(o).contains("raw correction"));assertTrue(o.conditions().contains("INCIDENT_AND_COVERAGE_UNVERIFIED"));
    }
    @ParameterizedTest @EnumSource(Format.class) void normalEmptyIsNotAnEarthquakeOrCoverage(Format f){var o=observe(f==Format.JSON?json("00","OK",0,"[]"):xml("00","OK",0,""),f);assertTrue(o.parsingSucceeded());assertTrue(o.providerNormal());assertFalse(o.earthquakeRowsReceived());assertTrue(o.conditions().contains("EMPTY_OBSERVATION_NOT_COVERAGE"));}
    @ParameterizedTest @CsvSource({"03,NODATA_ERROR","99,UNKNOWN_ERROR"}) void providerErrorIsNotNormalOrEmptySuccess(String code,String msg){for(var f:Format.values()){var o=observe(f==Format.JSON?json(code,msg,0,"[]"):xml(code,msg,0,""),f);assertTrue(o.parsingSucceeded());assertEquals(code,o.resultCode());assertEquals(msg,o.resultMsg());assertFalse(o.providerNormal());assertFalse(o.earthquakeRowsReceived());assertTrue(o.conditions().contains(code.equals("03")?"NO_DATA_OBSERVATION":"PROVIDER_ERROR"));}}
    @ParameterizedTest @ValueSource(ints={403,429,500,503}) void httpErrorsConsumeOnlyOneAttempt(int status){var calls=new AtomicInteger();var p=plan(Route.HUB,Format.JSON);var probe=probe((u,t)->{calls.incrementAndGet();return reply(status,json("99","UNKNOWN_ERROR",0,"[]"),Format.JSON);});var o=probe.observe(p,allowed(p));assertEquals(status,o.httpStatus());assertFalse(o.httpNormal());assertFalse(o.earthquakeRowsReceived());assertTrue(o.conditions().contains("HTTP_ERROR"));assertTrue(probe.observe(p,allowed(p)).conditions().contains("REQUEST_BUDGET_EXHAUSTED"));assertEquals(1,calls.get());}
    @ParameterizedTest @ValueSource(strings={"TIMEOUT","TRANSPORT"}) void uncertainRequestNeverRetriesOrLeaksCause(String reason){var calls=new AtomicInteger();var p=plan(Route.PORTAL,Format.JSON);var probe=probe((u,t)->{calls.incrementAndGet();throw new IllegalStateException(reason+" "+u+" "+KEY);});var o=probe.observe(p,allowed(p));assertTrue(o.conditions().contains("TRANSPORT_UNCERTAIN"));assertNull(o.httpStatus());assertFalse(o.parsingSucceeded());assertFalse(metadataJson(o).contains(KEY));probe.observe(p,allowed(p));assertEquals(1,calls.get());}
    @Test void zeroTotalWithActualRowIsExplicitContradiction(){var o=observe(json("00","OK",0,"["+item()+"]"),Format.JSON);assertEquals(1,o.itemCount());assertTrue(o.conditions().contains("TOTAL_COUNT_CONTRADICTION"));assertTrue(o.httpNormal());assertTrue(o.providerNormal());/* received rows != validated incident */assertTrue(o.earthquakeRowsReceived());}
    @ParameterizedTest @ValueSource(strings={"202611091200","20261109120030","202602301200","2026-11-09 12:00:00","0"}) void timestampShapesAreObservedWithoutInventedTimezone(String time){var o=observe(json("00","OK",1,"["+item().replace("202611091200",time)+"]"),Format.JSON);String shape=o.items().getFirst().fields().get("tmFc").format();assertEquals(time.equals("202611091200")?"VALID_12_DIGITS":time.equals("20261109120030")?"VALID_14_DIGITS":time.equals("202602301200")?"INVALID_DATE":"UNSUPPORTED",shape);assertFalse(metadataJson(o).contains("\"tmFc\":\""+time+"\""));}
    @Test void missingIdentityIsReportedNotFilledWith108(){var o=observe(json("00","OK",1,"[{\"tmEqk\":null}]"),Format.JSON);assertTrue(o.conditions().contains("INTERNAL_IDENTITY_INCOMPLETE"));assertFalse(o.items().getFirst().fields().get("stnId").present());assertEquals("NULL",o.items().getFirst().fields().get("tmEqk").type());}
    @Test void contentTypeAndProviderMessageCannotExfiltrateSecrets(){var p=plan(Route.PORTAL,Format.JSON);var o=probe((u,t)->new OfficialHttp.HeadersReply(200,json("99",KEY,0,"[]").getBytes(StandardCharsets.UTF_8),List.of(KEY),List.of("secret/"+KEY))).observe(p,allowed(p));String encoded=metadataJson(o);assertEquals("REDACTED_UNRECOGNIZED",o.resultMsg());assertEquals("UNRECOGNIZED",o.contentType());assertFalse(encoded.contains(KEY));assertFalse(encoded.contains("serviceKey="));assertFalse(encoded.contains("https://"));assertFalse(o.toString().contains(KEY));assertEquals("ProbeCredentials[redacted]",new Credentials(Map.of(Route.PORTAL,()->KEY)).toString());}
    @Test void xxeAndNonUtf8AndHtmlAreRejectedWithoutSecondaryIo(){for(byte[] bytes:List.of(("<!DOCTYPE response [<!ENTITY x SYSTEM 'file:///DO_NOT_OPEN'>]><response><header>&x;</header></response>").getBytes(StandardCharsets.UTF_8),new byte[]{(byte)0xc3,(byte)0x28},"<html>synthetic forbidden</html>".getBytes(StandardCharsets.UTF_8))){var p=plan(Route.PORTAL,Format.XML);var o=probe((u,t)->new OfficialHttp.HeadersReply(200,bytes,List.of())).observe(p,allowed(p));assertFalse(o.parsingSucceeded());assertTrue(o.conditions().contains("SCHEMA_INVALID"));}}
    @Test void fixedRoutesAndCredentialSuppliersCannotFallback(){var portal=new AtomicInteger();var hub=new AtomicInteger();var calls=new ArrayList<URI>();var probe=new EarthquakeApiProbe((u,t)->{calls.add(u);return reply(200,json("00","OK",0,"[]"),Format.JSON);},new Credentials(Map.of(Route.PORTAL,()->{portal.incrementAndGet();return KEY;},Route.HUB,()->{hub.incrementAndGet();return KEY;})),CLOCK);var p=plan(Route.PORTAL,Format.JSON);probe.observe(p,allowed(p));assertEquals(1,portal.get());assertEquals(0,hub.get());var uri=calls.getFirst();assertEquals("https",uri.getScheme());assertEquals("apis.data.go.kr",uri.getHost());assertEquals("/1360000/EqkInfoService/getEqkMsg",uri.getPath());assertTrue(uri.getRawQuery().contains("serviceKey=SYNTHETIC_SECRET%2B%2F%3DDO_NOT_LOG"));for(String q:List.of("fromTmFc=20261109","toTmFc=20261109","pageNo=1","numOfRows=1","dataType=JSON"))assertTrue(uri.getRawQuery().contains(q));assertFalse(uri.getRawQuery().contains("authKey="));var h=plan(Route.HUB,Format.JSON);probe.observe(h,allowed(h));assertEquals(1,hub.get());assertEquals("apihub.kma.go.kr",calls.getLast().getHost());assertTrue(calls.getLast().getRawQuery().contains("authKey="));assertFalse(calls.getLast().getRawQuery().contains("serviceKey="));}
    @Test void approvalMustMatchPlanExpiryKeyIpQuotaAndPolicy(){var p=plan(Route.PORTAL,Format.JSON);var calls=new AtomicInteger();var probe=probe((u,t)->{calls.incrementAndGet();throw new AssertionError();});var variants=List.of(new Authorization(p,CLOCK.instant(),CLOCK.instant().plusSeconds(100),1,true,true,true,true,"TEST:REF"),new Authorization(p,CLOCK.instant().plusSeconds(100),CLOCK.instant(),1,true,true,true,true,"TEST:REF"),new Authorization(p,CLOCK.instant().plusSeconds(100),CLOCK.instant().plusSeconds(100),2,true,true,true,true,"TEST:REF"),new Authorization(p,CLOCK.instant().plusSeconds(100),CLOCK.instant().plusSeconds(100),1,false,true,true,true,"TEST:REF"),new Authorization(p,CLOCK.instant().plusSeconds(100),CLOCK.instant().plusSeconds(100),1,true,false,true,true,"TEST:REF"),new Authorization(p,CLOCK.instant().plusSeconds(100),CLOCK.instant().plusSeconds(100),1,true,true,false,true,"TEST:REF"),new Authorization(p,CLOCK.instant().plusSeconds(100),CLOCK.instant().plusSeconds(100),1,true,true,true,false,"TEST:REF"),allowed(plan(Route.HUB,Format.JSON)));for(var a:variants)assertEquals(List.of("APPROVAL_REQUIRED"),probe.observe(p,a).conditions());assertEquals(0,calls.get());}
    @Test void sameRouteConcurrentCallsAndReusedProbeAreBounded()throws Exception{var count=new AtomicInteger();var probe=probe((u,t)->{count.incrementAndGet();return reply(200,json("00","OK",0,"[]"),Format.JSON);});try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var jobs=new ArrayList<Future<Observation>>();for(int i=0;i<20;i++)jobs.add(pool.submit(()->{var p=plan(Route.HUB,Format.JSON);return probe.observe(p,allowed(p));}));for(var j:jobs)j.get(5,TimeUnit.SECONDS);}assertEquals(1,count.get());}
    @Test void missingCredentialConsumesAttemptWithoutTryingOtherRoute(){var p=plan(Route.PORTAL,Format.JSON);var calls=new AtomicInteger();var probe=new EarthquakeApiProbe((u,t)->{calls.incrementAndGet();throw new AssertionError();},new Credentials(Map.of()),CLOCK);assertTrue(probe.observe(p,allowed(p)).conditions().contains("KEY_UNAVAILABLE"));assertTrue(probe.observe(p,allowed(p)).conditions().contains("REQUEST_BUDGET_EXHAUSTED"));assertEquals(0,calls.get());}
    Path approval(String additions)throws Exception{Path p=temp.resolve(UUID.randomUUID()+".properties");Files.writeString(p,"route=PORTAL\nfrom=2026-11-09\nto=2026-11-09\npage=1\nrows=1\nformat=JSON\nexpires-at=2026-11-10T03:05:00Z\nkey-valid-until=2026-11-10T04:00:00Z\nmax-requests=1\ndevelopment-api-approved=true\nallowed-ip-approved=true\nremaining-quota-approved=true\nmetadata-access-approved=true\napproval-reference=SYNTHETIC:TEST\nbody-storage=NONE\n"+additions);return p;}
    String[] args(Path file,String mode){return new String[]{mode,"--route=PORTAL","--from=2026-11-09","--to=2026-11-09","--page=1","--rows=1","--format=JSON","--approval-file="+file};}
    @Test void checkModeDoesNotReadCredentialsConstructSenderOrConsumeApproval()throws Exception{var p=approval("");var out=new ByteArrayOutputStream();assertEquals(0,EarthquakeProbeCli.run(args(p,"--check"),n->{throw new AssertionError();},()->{throw new AssertionError();},new PrintStream(out),CLOCK));assertTrue(out.toString().contains("NETWORK_NOT_USED_CREDENTIALS_NOT_READ"));assertFalse(Files.exists(p.resolveSibling(p.getFileName()+".consumed")));}
    @Test void cliSingleUseMarkerPreventsRestartOrManualAutomaticRetry()throws Exception{var p=approval("");var calls=new AtomicInteger();var env=new AtomicInteger();EarthquakeProbeCli.SenderFactory factory=()->new EarthquakeProbeCli.Session(){public OfficialHttp.HeadersReply get(URI u,Duration t){calls.incrementAndGet();return reply(403,"SYNTHETIC "+KEY,Format.JSON);}public void close(){}};var out=new ByteArrayOutputStream();assertEquals(3,EarthquakeProbeCli.run(args(p,"--execute-approved"),name->{assertEquals("EODIISSEO_PROBE_PORTAL_KEY",name);env.incrementAndGet();return KEY;},factory,new PrintStream(out),CLOCK));assertEquals(2,EarthquakeProbeCli.run(args(p,"--execute-approved"),name->{throw new AssertionError();},()->{throw new AssertionError();},new PrintStream(out),CLOCK));assertEquals(1,calls.get());assertEquals(1,env.get());assertFalse(out.toString().contains(KEY));assertFalse(Files.readString(p.resolveSibling(p.getFileName()+".consumed")).contains(KEY));}
    @ParameterizedTest @ValueSource(strings={"serviceKey=SYNTHETIC\n","body-storage=RAW\n","route=HUB\n"}) void extraOrDuplicateApprovalFieldsFailBeforeAnyRequest(String additions)throws Exception{var p=approval(additions);assertEquals(2,EarthquakeProbeCli.run(args(p,"--execute-approved"),name->{throw new AssertionError();},()->{throw new AssertionError();},new PrintStream(new ByteArrayOutputStream()),CLOCK));}
    @Test void standaloneCoreHasNoDatabaseProjectionWorkerOrAiReferences()throws Exception{
        for(Class<?> type:List.of(EarthquakeApiProbe.class,EarthquakeProbeCli.class)){String bytecode=new String(type.getResourceAsStream(type.getSimpleName()+".class").readAllBytes(),StandardCharsets.ISO_8859_1);for(String forbidden:List.of("java/sql/","javax/sql/","org/springframework/","CollectionCoordinator","Projection","JdbcTemplate","Outbox","Ollama","FCM"))assertFalse(bytecode.contains(forbidden),forbidden);}
        try(var jdbc=mockStatic(DriverManager.class)){var p=plan(Route.PORTAL,Format.JSON);probe((u,t)->reply(200,json("00","OK",1,"["+item()+"]"),Format.JSON)).observe(p,allowed(p));jdbc.verifyNoInteractions();}
    }
    @Test void duplicatedJsonKeysAndDeepXmlAndMissingItemsRemainUncertain(){
        var duplicate=observe(json("00","OK",1,"["+item()+"]").replace("\"totalCount\":1","\"totalCount\":1,\"totalCount\":0"),Format.JSON);
        assertFalse(duplicate.parsingSucceeded());assertTrue(duplicate.conditions().contains("SCHEMA_INVALID"));
        String deep="<response>"+"<nested>".repeat(20)+"SYNTHETIC"+"</nested>".repeat(20)+"</response>";
        assertFalse(observe(deep,Format.XML).parsingSucceeded());
        var absent=observe("{\"response\":{\"header\":{\"resultCode\":\"00\"},\"body\":{\"pageNo\":1,\"numOfRows\":1,\"totalCount\":0}}}",Format.JSON);
        assertTrue(absent.conditions().contains("MISSING_ITEMS_CONTAINER"));
    }
    @Test void approvalMarkerIsAtomicAcrossConcurrentCliExecutions()throws Exception{
        var p=approval("");var count=new AtomicInteger();EarthquakeProbeCli.SenderFactory factory=()->new EarthquakeProbeCli.Session(){public OfficialHttp.HeadersReply get(URI u,Duration t){count.incrementAndGet();return reply(200,json("00","OK",1,"["+item()+"]"),Format.JSON);}public void close(){}};
        try(var pool=Executors.newVirtualThreadPerTaskExecutor()){
            var futures=new ArrayList<Future<Integer>>();for(int i=0;i<10;i++)futures.add(pool.submit(()->EarthquakeProbeCli.run(args(p,"--execute-approved"),name->KEY,factory,new PrintStream(new ByteArrayOutputStream()),CLOCK)));
            int ok=0;for(var f:futures)if(f.get(5,TimeUnit.SECONDS)==0)ok++;assertEquals(1,ok);
        }assertEquals(1,count.get());
    }
    @Test void wrongDatePrecisionAndUnrecognisedSuccessMessageStayUncertain(){
        var wrong=observe(json("00","OK",1,"["+item().replace("202611091200","202611081200")+"]"),Format.JSON);
        assertTrue(wrong.conditions().contains("ANNOUNCEMENT_DATE_MISMATCH"));
        var precision=observe(json("00","OK",1,"["+item().replace("202611091200","20261109120030").replace("20261109115930","202611091159")+"]"),Format.JSON);
        assertTrue(precision.conditions().contains("ANNOUNCEMENT_TIME_PRECISION_UNVERIFIED"));assertTrue(precision.conditions().contains("OCCURRENCE_TIME_PRECISION_UNVERIFIED"));
        var unknown=observe(json("00","SYNTHETIC UNREVIEWED",1,"["+item()+"]"),Format.JSON);
        assertTrue(unknown.conditions().contains("PROVIDER_MESSAGE_UNRECOGNIZED"));assertEquals("REDACTED_UNRECOGNIZED",unknown.resultMsg());
    }
}